CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text, phone text, locale text NOT NULL DEFAULT 'fr-FR', created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS guest_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_key text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz);
CREATE TABLE IF NOT EXISTS diagnostic_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), guest_session_id uuid REFERENCES guest_sessions(id), category text, subcategory text, status text NOT NULL DEFAULT 'active', urgency text, risk_level text, diy_allowed boolean, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS diagnostic_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES diagnostic_sessions(id) ON DELETE CASCADE, role text NOT NULL, type text NOT NULL, content_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS diagnostic_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES diagnostic_sessions(id) ON DELETE CASCADE, message_id uuid, storage_key text NOT NULL, media_type text NOT NULL, consent_for_pro boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS repair_steps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES diagnostic_sessions(id) ON DELETE CASCADE, step_index int NOT NULL, instruction text NOT NULL, safety_note text, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE IF NOT EXISTS safety_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES diagnostic_sessions(id) ON DELETE CASCADE, flag text NOT NULL, severity text NOT NULL, action_taken text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES diagnostic_sessions(id), user_id uuid REFERENCES users(id), first_name text NOT NULL, phone text NOT NULL, city text NOT NULL, postal_code text NOT NULL, desired_time_window text, trade text NOT NULL, summary text NOT NULL, urgency text NOT NULL, consent_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'new', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS professionals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_name text NOT NULL, legal_name text, siren_siret text, phone text NOT NULL, email text NOT NULL, verification_status text NOT NULL DEFAULT 'unverified', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS professional_trades (professional_id uuid REFERENCES professionals(id) ON DELETE CASCADE, trade text NOT NULL, PRIMARY KEY(professional_id, trade));
CREATE TABLE IF NOT EXISTS professional_zones (professional_id uuid REFERENCES professionals(id) ON DELETE CASCADE, postal_prefix text NOT NULL, PRIMARY KEY(professional_id, postal_prefix));
CREATE TABLE IF NOT EXISTS lead_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid REFERENCES leads(id) ON DELETE CASCADE, professional_id uuid REFERENCES professionals(id), status text NOT NULL DEFAULT 'new', assigned_at timestamptz NOT NULL DEFAULT now(), viewed_at timestamptz, accepted_at timestamptz);
CREATE TABLE IF NOT EXISTS feedback (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid REFERENCES diagnostic_sessions(id), rating int CHECK (rating BETWEEN 1 AND 5), resolved boolean, comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS consent_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_id uuid NOT NULL, consent_type text NOT NULL, version text NOT NULL, granted boolean NOT NULL, timestamp timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS analytics_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_name text NOT NULL, anonymous_id text, session_id uuid, properties_json jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_diagnostic_sessions_created ON diagnostic_sessions(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_leads_status_created ON leads(status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_media_session ON diagnostic_media(session_id) WHERE deleted_at IS NULL;
